/// One block-plan case: the PRNG state after all laps for both lap-count variants
/// and the sizes of the blocks that are really present.
pub struct PlanCase {
    pub enc_seed: u64,
    pub plain_len: usize,
    /// `laps = (len >> 14) + (len & 0x3FFF != 0)` (ree-save-editor).
    pub state: u64,
    /// `laps = (len >> 14) + 1` (MandarinJuice); differs only for multiples of 0x4000.
    pub state_extra_lap: u64,
    pub blocks: &'static [usize],
}

