/// A complete `mandarin::encrypt` output, described by its length, two digests and
/// its first 32 bytes. The plaintext is `sample_bytes(plain_len)`.
pub struct CipherCase {
    pub name: &'static str,
    pub enc_seed: u64,
    pub rsa_seed: u64,
    pub key64: u64,
    pub plain_len: usize,
    /// Use `(len >> 14) + 1` laps (only set for multiples of 0x4000).
    pub extra_lap: bool,
    pub out_len: usize,
    pub murmur3: u32,
    pub cityhash64: u64,
    pub head_hex: &'static str,
}

